corrected_code:
const express = require('express');
const { Queue } = require('bullmq');
const Redis = require('ioredis');

const app = express();
const redis = new Redis(process.env.REDIS_URL);

const requireSupportAgent = (req, res, next) => {
  if (req.user && req.user.role === 'support_agent') {
    return next();
  }
  res.status(403).json({ error: 'Support role required' });
};

app.post('/admin/queues/:queueName/jobs/:jobId/retry', requireSupportAgent, async (req, res) => {
  const { queueName, jobId } = req.params;
  const agentTenantId = req.user.assignedTenantId;

  const queue = new Queue(queueName, { connection: redis });
  const job = await queue.getJob(jobId);

  if (!job) {
    return res.status(404).json({ error: 'Job not found in queue' });
  }

  // Enforce object-level tenant isolation on the BullMQ job data payload
  if (job.data && job.data.tenantId !== agentTenantId) {
    return res.status(403).json({ error: 'Access denied: job belongs to another tenant' });
  }

  await job.retry();
  res.json({ success: true, jobId, queueName, status: 'retried' });
});

app.listen(8006);
